pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(value) = bytes
        .strip_prefix(r#"{"v":2,"type":"hello","value":""#)
        .and_then(|value| value.strip_suffix("\"}"))
    {
        return Ok(Msg::Hello(value.into()));
    }
    if let Some(sequence) = bytes
        .strip_prefix(r#"{"v":2,"type":"heartbeat","seq":"#)
        .and_then(|value| value.strip_suffix("}"))
        .and_then(|value| value.parse().ok())
    {
        return Ok(Msg::Heartbeat(sequence));
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(r#"{{"v":2,"type":"hello","value":"{}"}}"#, value),
        Msg::Heartbeat(sequence) => {
            format!(r#"{{"v":2,"type":"heartbeat","seq":{}}}"#, sequence)
        },
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};
    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_roundtrips_as_v2_frame() {
        let msg = Msg::Hello("world".into());
        assert_eq!(encode(&msg), r#"{"v":2,"type":"hello","value":"world"}"#);
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Hello(value)) if value == "world"));
    }

    #[test]
    fn heartbeat_roundtrips_with_sequence_number() {
        let msg = Msg::Heartbeat(42);
        assert_eq!(encode(&msg), r#"{"v":2,"type":"heartbeat","seq":42}"#);
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Heartbeat(sequence)) if sequence == 42));
    }}
